/**
 * meeting.service.js — Phase 3: Live Interview Meeting Scheduling
 *
 * Manages the lifecycle of InterviewMeetingSession documents.
 * Meetings are coordination layers that live inside existing conversations.
 * The meeting link is generated by a provider abstraction (Jitsi / Google Meet).
 *
 * Rule: All business logic lives here. Controller stays thin.
 */

import mongoose from "mongoose";
import crypto from "crypto";

import { AppError } from "../../utils/appError.js";
import { Conversation, Message } from "../chat/chat.model.js";
import { emitToConversation } from "../chat/chat.realtime.js";
import { InterviewMeetingSession } from "./interview.model.js";

// ── Helpers ───────────────────────────────────────────────────────────────────

function toObjectId(value, msg = "Invalid identifier.") {
  if (!mongoose.Types.ObjectId.isValid(value)) throw new AppError(msg, 400);
  return new mongoose.Types.ObjectId(value);
}

/**
 * Serializes an InterviewMeetingSession document to a plain object safe for
 * API responses and socket payloads.
 */
function serializeMeeting(meeting) {
  return {
    id: String(meeting._id),
    conversationId: String(meeting.conversationId),
    interviewSessionId: meeting.interviewSessionId ? String(meeting.interviewSessionId) : null,
    organizerId: String(meeting.organizerId),
    participantId: String(meeting.participantId),
    provider: meeting.provider,
    meetingLink: meeting.meetingLink ?? null,
    scheduledAt: meeting.scheduledAt instanceof Date
      ? meeting.scheduledAt.toISOString()
      : new Date(meeting.scheduledAt).toISOString(),
    duration: meeting.duration,
    status: meeting.status,
    notes: meeting.notes ?? null,
    scheduleRequestMessageId: meeting.scheduleRequestMessageId
      ? String(meeting.scheduleRequestMessageId)
      : null,
    meetingCardMessageId: meeting.meetingCardMessageId
      ? String(meeting.meetingCardMessageId)
      : null,
    createdAt: meeting.createdAt
  };
}

/**
 * Ensures the requesting user is a participant of the given conversation.
 * Throws 403 if not.
 */
async function assertConversationParticipant(conversationId, userId) {
  const conversation = await Conversation.findById(conversationId)
    .select("participants")
    .lean();

  if (!conversation) throw new AppError("Conversation not found.", 404);

  const participantIds = conversation.participants.map(String);
  if (!participantIds.includes(String(userId))) {
    throw new AppError("You are not a participant of this conversation.", 403);
  }

  return conversation;
}

/**
 * Posts a message into the conversation timeline and emits it via socket.
 */
async function postMeetingMessage(conversationId, senderId, type, content, metadata = {}) {
  const message = await Message.create({
    conversationId,
    senderId,
    type,
    content,
    metadata
  });

  // Emit to all conversation members in realtime
  emitToConversation(String(conversationId), "receive_message", {
    ...message.toObject(),
    id: String(message._id)
  });

  return message;
}

// ── Provider Abstraction ──────────────────────────────────────────────────────

/**
 * Generates a Jitsi meeting link.
 * Format: https://meet.jit.si/rolebuddy-<uuid>
 * Jitsi is fully open — no API key needed.
 */
function generateJitsiLink() {
  const roomId = crypto.randomBytes(12).toString("hex");
  return `https://meet.jit.si/rolebuddy-${roomId}`;
}

/**
 * Returns a placeholder for Google Meet links.
 * Real implementation requires Google Calendar API / Admin SDK.
 * For now, we inform the user that the link must be created manually and
 * provide a Google Meet landing URL as fallback.
 */
function generateGoogleMeetLink() {
  // Google Meet does not offer a public API for creating rooms without
  // a Calendar event. In Phase 3 we surface a placeholder that the organizer
  // replaces manually, or use Calendar integration (already present for slots).
  return "https://meet.google.com/new";
}

/**
 * Generates a meeting link for the given provider.
 * Extensible: add new providers here without touching the rest of the service.
 */
function generateMeetingLink(provider) {
  switch (provider) {
    case "jitsi":
      return generateJitsiLink();
    case "google_meet":
      return generateGoogleMeetLink();
    default:
      throw new AppError(`Unsupported meeting provider: ${provider}`, 400);
  }
}

// ── Service Functions ─────────────────────────────────────────────────────────

/**
 * POST /api/interviews/meetings
 *
 * Schedules a new live interview meeting inside an existing conversation.
 * Creates a `interview_schedule_request` message in the conversation timeline.
 * Emits `interview_schedule_requested` socket event.
 */
export async function scheduleMeeting(organizerId, payload) {
  const {
    conversationId,
    interviewSessionId = null,
    provider,
    meetingLink = null,
    scheduledAt,
    duration = 30,
    notes = null
  } = payload;


  // ── Validation ──
  if (!conversationId) throw new AppError("conversationId is required.", 400);
  if (!provider) throw new AppError("provider is required.", 400);
  if (!["jitsi", "google_meet"].includes(provider)) {
    throw new AppError("provider must be one of: jitsi, google_meet.", 400);
  }
  if (!scheduledAt) throw new AppError("scheduledAt is required.", 400);

  const parsedScheduledAt = new Date(scheduledAt);
  if (Number.isNaN(parsedScheduledAt.getTime())) {
    throw new AppError("scheduledAt must be a valid datetime string.", 400);
  }
  if (parsedScheduledAt.getTime() <= Date.now()) {
    throw new AppError("scheduledAt must be a future date and time.", 400);
  }

  const validDurations = [15, 30, 45, 60, 90, 120];
  if (!validDurations.includes(Number(duration))) {
    throw new AppError(`duration must be one of: ${validDurations.join(", ")} minutes.`, 400);
  }

  // ── Access ──
  const conversation = await assertConversationParticipant(conversationId, organizerId);
  const participantId = conversation.participants
    .map(String)
    .find((id) => id !== String(organizerId));

  if (!participantId) throw new AppError("Could not identify the other conversation participant.", 500);

  // ── Create meeting session ──
  const finalMeetingLink = provider === "jitsi" ? generateJitsiLink() : meetingLink;

  const meetingSession = await InterviewMeetingSession.create({
    conversationId: toObjectId(conversationId),
    interviewSessionId: interviewSessionId ? toObjectId(interviewSessionId) : null,
    organizerId: toObjectId(organizerId),
    participantId: toObjectId(participantId),
    provider,
    meetingLink: finalMeetingLink,
    scheduledAt: parsedScheduledAt,
    duration: Number(duration),
    status: "pending",
    notes: notes ?? null
  });


  // ── Post schedule request message into conversation ──
  const content = `📅 Live interview scheduled for ${parsedScheduledAt.toLocaleString()}.`;
  const requestMessage = await postMeetingMessage(
    conversationId,
    organizerId,
    "interview_schedule_request",
    content,
    {
      meetingId: String(meetingSession._id),
      provider,
      scheduledAt: parsedScheduledAt.toISOString(),
      duration: Number(duration),
      notes: notes ?? null,
      status: "pending"
    }
  );

  // ── Update meeting with message reference ──
  meetingSession.scheduleRequestMessageId = requestMessage._id;
  await meetingSession.save();

  // ── Emit socket event to conversation room ──
  emitToConversation(String(conversationId), "interview_schedule_requested", {
    meeting: serializeMeeting(meetingSession)
  });

  return { meeting: serializeMeeting(meetingSession) };
}

/**
 * POST /api/interviews/meetings/:meetingId/accept
 *
 * Accepts a pending meeting request. Generates the meeting link.
 * Posts `interview_meeting_card` message and emits `interview_meeting_created` event.
 */
export async function acceptMeeting(userId, meetingId) {
  const meeting = await InterviewMeetingSession.findById(meetingId);
  if (!meeting) throw new AppError("Meeting not found.", 404);

  // Only the participant (non-organizer) can accept
  if (String(meeting.participantId) !== String(userId)) {
    throw new AppError("Only the invited participant can accept a meeting request.", 403);
  }

  if (meeting.status !== "pending") {
    throw new AppError(`Cannot accept a meeting with status '${meeting.status}'.`, 409);
  }

  // Use the link saved in the DB (generated on schedule for Jitsi, or provided for Google Meet),
  // fallback to generating one if missing (legacy safety).
  const finalMeetingLink = meeting.meetingLink || generateMeetingLink(meeting.provider);

  meeting.status = "scheduled";
  meeting.meetingLink = finalMeetingLink;
  await meeting.save();


  // Post meeting card into conversation timeline
  const cardMessage = await postMeetingMessage(
    meeting.conversationId,
    userId,
    "interview_meeting_card",
    `✅ Meeting confirmed! Join at ${finalMeetingLink}`,
    {
      meetingId: String(meeting._id),
      provider: meeting.provider,
      meetingLink: finalMeetingLink,
      scheduledAt: meeting.scheduledAt.toISOString(),

      duration: meeting.duration,
      notes: meeting.notes ?? null,
      status: "scheduled"
    }
  );

  meeting.meetingCardMessageId = cardMessage._id;
  await meeting.save();

  // Post system message for the declined user context
  await postMeetingMessage(
    meeting.conversationId,
    userId,
    "interview_schedule_system",
    "Meeting request accepted. Both participants can now join the meeting.",
    {
      meetingId: String(meeting._id),
      kind: "meeting_accepted",
      status: "scheduled"
    }
  );

  // Emit realtime event
  emitToConversation(String(meeting.conversationId), "interview_meeting_created", {
    meeting: serializeMeeting(meeting)
  });

  return { meeting: serializeMeeting(meeting) };
}

/**
 * POST /api/interviews/meetings/:meetingId/decline
 *
 * Declines a pending meeting request.
 * Posts `interview_schedule_system` message and emits `interview_meeting_cancelled` event.
 */
export async function declineMeeting(userId, meetingId) {
  const meeting = await InterviewMeetingSession.findById(meetingId);
  if (!meeting) throw new AppError("Meeting not found.", 404);

  // Either participant can decline
  const isParticipant =
    String(meeting.organizerId) === String(userId) ||
    String(meeting.participantId) === String(userId);

  if (!isParticipant) {
    throw new AppError("You are not a participant of this meeting.", 403);
  }

  if (!["pending"].includes(meeting.status)) {
    throw new AppError(`Cannot decline a meeting with status '${meeting.status}'.`, 409);
  }

  meeting.status = "declined";
  await meeting.save();

  await postMeetingMessage(
    meeting.conversationId,
    userId,
    "interview_schedule_system",
    "Meeting request was declined.",
    {
      meetingId: String(meeting._id),
      kind: "meeting_declined",
      status: "declined"
    }
  );

  emitToConversation(String(meeting.conversationId), "interview_meeting_cancelled", {
    meeting: serializeMeeting(meeting)
  });

  return { meeting: serializeMeeting(meeting) };
}

/**
 * POST /api/interviews/meetings/:meetingId/cancel
 *
 * Cancels a scheduled/pending meeting.
 * Only the organizer can cancel. Posts system message, emits socket event.
 */
export async function cancelMeeting(userId, meetingId) {
  const meeting = await InterviewMeetingSession.findById(meetingId);
  if (!meeting) throw new AppError("Meeting not found.", 404);

  // Both organizer and participant can cancel (per product decision — mutual cancellation)
  const isParticipant =
    String(meeting.organizerId) === String(userId) ||
    String(meeting.participantId) === String(userId);

  if (!isParticipant) {
    throw new AppError("You are not a participant of this meeting.", 403);
  }

  if (!["pending", "accepted", "scheduled"].includes(meeting.status)) {
    throw new AppError(`Cannot cancel a meeting with status '${meeting.status}'.`, 409);
  }

  meeting.status = "cancelled";
  await meeting.save();

  await postMeetingMessage(
    meeting.conversationId,
    userId,
    "interview_schedule_system",
    "Meeting was cancelled.",
    {
      meetingId: String(meeting._id),
      kind: "meeting_cancelled",
      status: "cancelled"
    }
  );

  emitToConversation(String(meeting.conversationId), "interview_meeting_cancelled", {
    meeting: serializeMeeting(meeting)
  });

  return { meeting: serializeMeeting(meeting) };
}

/**
 * GET /api/interviews/meetings/:conversationId
 *
 * Returns all meetings for a conversation, sorted by scheduledAt descending.
 * Access-controlled: requester must be a conversation participant.
 */
export async function getConversationMeetings(conversationId, userId) {
  await assertConversationParticipant(conversationId, userId);

  const meetings = await InterviewMeetingSession
    .find({ conversationId: toObjectId(conversationId) })
    .sort({ createdAt: -1 })
    .lean();

  return { meetings: meetings.map(serializeMeeting) };
}
